CREATE TABLE team_issue_sequences (
  team_id TEXT PRIMARY KEY REFERENCES teams(id),
  last_sequence INTEGER NOT NULL CHECK (last_sequence > 0),
  updated_at TEXT NOT NULL
);

INSERT INTO team_issue_sequences (team_id, last_sequence, updated_at)
SELECT team_id, MAX(sequence_number), MAX(updated_at)
FROM issues
GROUP BY team_id;

CREATE TABLE magic_links (
 id TEXT PRIMARY KEY, operator_id TEXT NOT NULL REFERENCES operators(id), token_hash TEXT NOT NULL UNIQUE,
 return_to TEXT NOT NULL, expires_at TEXT NOT NULL, consumed_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE local_mail_outbox (
 id TEXT PRIMARY KEY, recipient TEXT NOT NULL, sign_in_url TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE access_rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at TEXT NOT NULL);

CREATE TABLE issue_comments (
 id TEXT PRIMARY KEY, issue_id TEXT NOT NULL REFERENCES issues(id), actor_operator_id TEXT NOT NULL REFERENCES operators(id),
 body TEXT, edited_at TEXT, deleted_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE INDEX issue_comments_issue_idx ON issue_comments(issue_id,created_at);
CREATE TABLE issue_files (
 id TEXT PRIMARY KEY, issue_id TEXT NOT NULL REFERENCES issues(id), actor_operator_id TEXT NOT NULL REFERENCES operators(id),
 name TEXT NOT NULL, content_type TEXT NOT NULL, bytes INTEGER NOT NULL CHECK(bytes>0), blob_key TEXT NOT NULL UNIQUE,
 deleted_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE INDEX issue_files_issue_idx ON issue_files(issue_id,created_at);
CREATE TABLE audit_records (
 id TEXT PRIMARY KEY, actor_operator_id TEXT, action TEXT NOT NULL, subject_identifier TEXT NOT NULL,
 subject_id TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);

-- A deletion request is durable before any R2 work. deleted_at alone is not a
-- physical-erasure receipt for old pending uploads.
ALTER TABLE issue_files ADD COLUMN writer_settled INTEGER NOT NULL DEFAULT 1 CHECK(writer_settled IN (0,1));
ALTER TABLE issue_files ADD COLUMN removal_requested_at TEXT;
ALTER TABLE issue_files ADD COLUMN removal_actor_operator_id TEXT REFERENCES operators(id);
ALTER TABLE issue_files ADD COLUMN removal_confirmed_at TEXT;
ALTER TABLE issue_files ADD COLUMN cleanup_error TEXT;
ALTER TABLE issue_files ADD COLUMN content_sha256 TEXT;

UPDATE issue_files SET writer_settled=0 WHERE state='pending';
-- Preserve old timestamps/history and retain exact keys for orphan recovery.
UPDATE issue_files SET removal_requested_at=deleted_at WHERE deleted_at IS NOT NULL;
CREATE INDEX issue_files_removal_idx ON issue_files(removal_confirmed_at,removal_requested_at,updated_at);

-- Preserve existing source evidence and its assertions byte-for-byte.
ALTER TABLE evidence_revisions ADD COLUMN origin_kind TEXT NOT NULL DEFAULT 'source' CHECK(origin_kind IN ('source','operator'));
ALTER TABLE evidence_revisions ADD COLUMN actor_operator_id TEXT REFERENCES operators(id);
ALTER TABLE evidence_revisions ADD COLUMN link TEXT;
ALTER TABLE evidence_revisions ADD COLUMN customer_reports_json TEXT NOT NULL DEFAULT '[]';

-- Named automation attribution is additive; original operator actors and
-- intake decisions/timestamps remain unchanged.
ALTER TABLE issue_activity ADD COLUMN actor_name TEXT;

-- Additive schema draft. Integrator assigns the next migration number; never
-- replace an applied migration. All epoch timestamps are milliseconds.
CREATE TABLE oa_operators (
 id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL,
 role TEXT NOT NULL CHECK(role IN ('owner','admin','member')),
 status TEXT NOT NULL CHECK(status IN ('invited','active','inactive')),
 version INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL
);
CREATE TABLE oa_bootstrap (singleton INTEGER PRIMARY KEY CHECK(singleton=1), claim_id TEXT NOT NULL UNIQUE, claimed_at INTEGER NOT NULL);
CREATE TABLE oa_tokens (
 id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE,
 kind TEXT NOT NULL CHECK(kind IN ('magic','invite')),
 operator_id TEXT NOT NULL REFERENCES oa_operators(id), operator_version INTEGER NOT NULL,
 issuer_id TEXT REFERENCES oa_operators(id), issuer_version INTEGER,
 return_to TEXT NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL,
 consumed_at INTEGER, revoked_at INTEGER,
 CHECK((kind='invite' AND issuer_id IS NOT NULL AND issuer_version IS NOT NULL)
    OR (kind='magic' AND issuer_id IS NULL AND issuer_version IS NULL))
);
CREATE TABLE oa_sessions (
 id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE,
 operator_id TEXT NOT NULL REFERENCES oa_operators(id), operator_version INTEGER NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN ('native','review','oidc','password')),
 source_token_id TEXT UNIQUE REFERENCES oa_tokens(id),
 created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER
);
CREATE INDEX oa_sessions_operator ON oa_sessions(operator_id);
CREATE TABLE oa_external_identities (
 issuer TEXT NOT NULL, subject TEXT NOT NULL, operator_id TEXT NOT NULL REFERENCES oa_operators(id),
 PRIMARY KEY(issuer, subject)
);
CREATE TABLE oa_limits (key TEXT PRIMARY KEY, window INTEGER NOT NULL, count INTEGER NOT NULL);
CREATE TRIGGER oa_preserve_last_owner_update BEFORE UPDATE OF status,role ON oa_operators
 WHEN OLD.role='owner' AND OLD.status='active' AND (NEW.role!='owner' OR NEW.status!='active')
 AND (SELECT COUNT(*) FROM oa_operators WHERE role='owner' AND status='active') <= 1
 BEGIN SELECT RAISE(ABORT, 'last_owner'); END;
CREATE TRIGGER oa_preserve_last_owner_delete BEFORE DELETE ON oa_operators
 WHEN OLD.role='owner' AND OLD.status='active'
 AND (SELECT COUNT(*) FROM oa_operators WHERE role='owner' AND status='active') <= 1
 BEGIN SELECT RAISE(ABORT, 'last_owner'); END;
-- A status/role change invalidates every preexisting session and link, including
-- after a later reactivation. Keep this invariant for direct administrative SQL.
CREATE TRIGGER oa_operator_version AFTER UPDATE OF status,role ON oa_operators
 WHEN OLD.status != NEW.status OR OLD.role != NEW.role
 BEGIN UPDATE oa_operators SET version=OLD.version+1 WHERE id=NEW.id; END;

-- Vector's product IDs and applied native history remain intact. Every operator
-- has equal authority: Base owner is an implementation role, never a product role.
CREATE TABLE vector_auth_operators (
 auth_id TEXT PRIMARY KEY REFERENCES oa_operators(id),
 operator_id TEXT NOT NULL UNIQUE REFERENCES operators(id)
);
INSERT INTO oa_operators(id,email,display_name,role,status,created_at)
 SELECT id,lower(email),name,'owner',CASE WHEN removed_at IS NULL THEN 'active' ELSE 'inactive' END,
 CAST(unixepoch(created_at)*1000 AS INTEGER) FROM operators;
INSERT INTO vector_auth_operators(auth_id,operator_id) SELECT id,id FROM operators;
INSERT INTO oa_bootstrap(singleton,claim_id,claimed_at)
 SELECT 1,'vector-existing-operator-import',CAST(unixepoch('now')*1000 AS INTEGER)
 WHERE EXISTS(SELECT 1 FROM operators);
-- Configured first-owner bootstrap, explicit sample seeding and legacy imports
-- all use the existing product insert boundary. No request email creates a user.
CREATE TRIGGER vector_operator_auth_insert AFTER INSERT ON operators
 BEGIN
 INSERT INTO oa_operators(id,email,display_name,role,status,created_at)
 SELECT NEW.id,lower(NEW.email),NEW.name,'owner',CASE WHEN NEW.removed_at IS NULL THEN 'active' ELSE 'inactive' END,
 CAST(unixepoch(NEW.created_at)*1000 AS INTEGER)
 WHERE NOT EXISTS(SELECT 1 FROM oa_operators WHERE email=lower(NEW.email));
 INSERT INTO vector_auth_operators(auth_id,operator_id)
 SELECT id,NEW.id FROM oa_operators WHERE email=lower(NEW.email);
 INSERT INTO oa_bootstrap(singleton,claim_id,claimed_at) VALUES(1,'vector-configured-owner',CAST(unixepoch('now')*1000 AS INTEGER)) ON CONFLICT DO NOTHING;
 END;
-- This runs in the very same transaction as OPS-004 transfers and anonymisation.
CREATE TRIGGER vector_operator_auth_remove AFTER UPDATE OF removed_at ON operators
 WHEN OLD.removed_at IS NULL AND NEW.removed_at IS NOT NULL
 BEGIN
 UPDATE oa_tokens SET revoked_at=CAST(unixepoch('now')*1000 AS INTEGER)
 WHERE operator_id IN(SELECT auth_id FROM vector_auth_operators WHERE operator_id=NEW.id)
 OR issuer_id IN(SELECT auth_id FROM vector_auth_operators WHERE operator_id=NEW.id);
 UPDATE oa_sessions SET revoked_at=CAST(unixepoch('now')*1000 AS INTEGER)
 WHERE operator_id IN(SELECT auth_id FROM vector_auth_operators WHERE operator_id=NEW.id);
 UPDATE oa_operators SET status='inactive',email=NEW.email,display_name='Removed operator'
 WHERE id IN(SELECT auth_id FROM vector_auth_operators WHERE operator_id=NEW.id);
 END;

-- Expand durable administration history; existing product rows remain unchanged.
CREATE TABLE administration_audit_details (
  audit_id TEXT PRIMARY KEY REFERENCES audit_records(id),
  previous_value_json TEXT,
  next_value_json TEXT
);
CREATE TABLE team_issue_history (
  team_id TEXT PRIMARY KEY REFERENCES teams(id),
  first_issue_at TEXT NOT NULL
);
-- Prefixes can be released before the first issue, but allocated numbers can
-- never be reused, even when another team subsequently takes that prefix.
CREATE TABLE issue_prefix_sequences (
  workspace_id TEXT NOT NULL REFERENCES workspace_settings(id),
  identifier_prefix TEXT NOT NULL COLLATE NOCASE,
  last_sequence INTEGER NOT NULL CHECK (last_sequence > 0),
  updated_at TEXT NOT NULL,
  PRIMARY KEY (workspace_id,identifier_prefix)
);
INSERT INTO issue_prefix_sequences(workspace_id,identifier_prefix,last_sequence,updated_at)
SELECT workspace_id,identifier_prefix,MAX(last_sequence),MAX(updated_at) FROM (
  SELECT t.workspace_id,t.identifier_prefix,s.last_sequence,s.updated_at
  FROM team_issue_sequences s JOIN teams t ON t.id=s.team_id
  UNION ALL
  SELECT t.workspace_id,i.origin_prefix,i.sequence_number,i.updated_at
  FROM issues i JOIN teams t ON t.id=i.team_id
) GROUP BY workspace_id,identifier_prefix COLLATE NOCASE;
-- Before this migration, reservations are the only durable evidence of an
-- originating issue after deletion. Preserve that legacy history conservatively.
-- New reservations alone do not freeze a prefix; only committed issues do.
INSERT INTO team_issue_history(team_id,first_issue_at)
SELECT team_id,MIN(at) FROM (
  SELECT team_id,created_at AS at FROM issues
  UNION ALL SELECT team_id,updated_at AS at FROM team_issue_sequences
  UNION ALL SELECT json_extract(previous_value_json,'$.teamId'),created_at FROM issue_activity
    WHERE kind='issue.team_moved' AND json_valid(previous_value_json)
  UNION ALL SELECT json_extract(next_value_json,'$.teamId'),created_at FROM issue_activity
    WHERE kind='issue.team_moved' AND json_valid(next_value_json)
) WHERE team_id IN (SELECT id FROM teams) GROUP BY team_id;
CREATE TRIGGER remember_issue_team_insert AFTER INSERT ON issues BEGIN
  INSERT OR IGNORE INTO team_issue_history(team_id,first_issue_at) VALUES(NEW.team_id,NEW.created_at);
  INSERT INTO issue_prefix_sequences(workspace_id,identifier_prefix,last_sequence,updated_at)
    SELECT workspace_id,NEW.origin_prefix,NEW.sequence_number,NEW.updated_at FROM teams WHERE id=NEW.team_id
    ON CONFLICT(workspace_id,identifier_prefix) DO UPDATE
    SET last_sequence=excluded.last_sequence,updated_at=excluded.updated_at
    WHERE excluded.last_sequence>issue_prefix_sequences.last_sequence;
END;
CREATE TRIGGER remember_issue_team_move AFTER UPDATE OF team_id ON issues BEGIN
  INSERT OR IGNORE INTO team_issue_history(team_id,first_issue_at) VALUES(NEW.team_id,NEW.updated_at);
END;
CREATE TRIGGER team_prefix_valid_insert BEFORE INSERT ON teams
WHEN length(NEW.identifier_prefix) NOT BETWEEN 2 AND 10 OR NEW.identifier_prefix GLOB '*[^A-Z]*'
BEGIN SELECT RAISE(ABORT,'invalid_team_prefix'); END;
CREATE TRIGGER team_prefix_valid_update BEFORE UPDATE OF identifier_prefix ON teams
WHEN NEW.identifier_prefix<>OLD.identifier_prefix COLLATE BINARY AND (length(NEW.identifier_prefix) NOT BETWEEN 2 AND 10 OR NEW.identifier_prefix GLOB '*[^A-Z]*')
BEGIN SELECT RAISE(ABORT,'invalid_team_prefix'); END;
CREATE TRIGGER team_prefix_history BEFORE UPDATE OF identifier_prefix ON teams
WHEN NEW.identifier_prefix<>OLD.identifier_prefix COLLATE BINARY AND (
 EXISTS(SELECT 1 FROM team_issue_history WHERE team_id=OLD.id) OR
 EXISTS(SELECT 1 FROM issues WHERE team_id=OLD.id))
BEGIN SELECT RAISE(ABORT,'team_prefix_frozen'); END;

-- Retain the existing per-team counter as a mirror for old application SQL.
-- These triggers share the reservation transaction and never create issue history.
CREATE TRIGGER remember_prefix_reservation_insert AFTER INSERT ON team_issue_sequences BEGIN
  INSERT INTO issue_prefix_sequences(workspace_id,identifier_prefix,last_sequence,updated_at)
    SELECT workspace_id,identifier_prefix,NEW.last_sequence,NEW.updated_at FROM teams WHERE id=NEW.team_id
    ON CONFLICT(workspace_id,identifier_prefix) DO UPDATE
    SET last_sequence=excluded.last_sequence,updated_at=excluded.updated_at
    WHERE excluded.last_sequence>issue_prefix_sequences.last_sequence;
END;
CREATE TRIGGER remember_prefix_reservation_update AFTER UPDATE OF last_sequence ON team_issue_sequences BEGIN
  INSERT INTO issue_prefix_sequences(workspace_id,identifier_prefix,last_sequence,updated_at)
    SELECT workspace_id,identifier_prefix,NEW.last_sequence,NEW.updated_at FROM teams WHERE id=NEW.team_id
    ON CONFLICT(workspace_id,identifier_prefix) DO UPDATE
    SET last_sequence=excluded.last_sequence,updated_at=excluded.updated_at
    WHERE excluded.last_sequence>issue_prefix_sequences.last_sequence;
END;
CREATE TRIGGER sync_new_team_prefix_sequence AFTER INSERT ON teams BEGIN
  INSERT INTO team_issue_sequences(team_id,last_sequence,updated_at)
    SELECT NEW.id,last_sequence,updated_at FROM issue_prefix_sequences
    WHERE workspace_id=NEW.workspace_id AND identifier_prefix=NEW.identifier_prefix;
END;
CREATE TRIGGER sync_changed_team_prefix_sequence AFTER UPDATE OF identifier_prefix ON teams
WHEN NEW.identifier_prefix<>OLD.identifier_prefix COLLATE BINARY BEGIN
  DELETE FROM team_issue_sequences WHERE team_id=NEW.id;
  INSERT INTO team_issue_sequences(team_id,last_sequence,updated_at)
    SELECT NEW.id,last_sequence,updated_at FROM issue_prefix_sequences
    WHERE workspace_id=NEW.workspace_id AND identifier_prefix=NEW.identifier_prefix;
END;

-- Additive collaboration state. Retain this ledger on application-code rollback.
CREATE TABLE issue_followers (
 issue_id TEXT NOT NULL REFERENCES issues(id) ON DELETE CASCADE,
 operator_id TEXT NOT NULL REFERENCES operators(id) ON DELETE CASCADE,
 created_at TEXT NOT NULL, PRIMARY KEY(issue_id,operator_id)
);
CREATE INDEX issue_followers_operator ON issue_followers(operator_id,issue_id);
CREATE TABLE issue_notification_mutes (
 issue_id TEXT NOT NULL REFERENCES issues(id) ON DELETE CASCADE,
 operator_id TEXT NOT NULL REFERENCES operators(id) ON DELETE CASCADE,
 PRIMARY KEY(issue_id,operator_id)
);
CREATE TABLE notification_preferences (
 operator_id TEXT PRIMARY KEY REFERENCES operators(id) ON DELETE CASCADE,
 email_enabled INTEGER NOT NULL CHECK(email_enabled IN (0,1))
);
CREATE TABLE notification_type_mutes (
 operator_id TEXT NOT NULL REFERENCES operators(id) ON DELETE CASCADE,
 kind TEXT NOT NULL CHECK(kind IN ('assignment','mention','comment','intake_return','unblocked')),
 PRIMARY KEY(operator_id,kind)
);
CREATE TABLE issue_mentions (
 issue_id TEXT NOT NULL REFERENCES issues(id) ON DELETE CASCADE,
 body_key TEXT NOT NULL,
 comment_id TEXT REFERENCES issue_comments(id) ON DELETE CASCADE,
 operator_id TEXT NOT NULL REFERENCES operators(id) ON DELETE CASCADE,
 PRIMARY KEY(issue_id,body_key,operator_id),
 CHECK((body_key='description' AND comment_id IS NULL) OR (comment_id IS NOT NULL AND body_key=comment_id))
);
CREATE TABLE issue_deferral_origins (
 issue_id TEXT PRIMARY KEY REFERENCES issues(id) ON DELETE CASCADE,
 decision_id TEXT NOT NULL UNIQUE REFERENCES intake_decisions(id) ON DELETE CASCADE
);
-- Retain finalized source identity even when every cause was muted. Replaying
-- a receipt must never backfill previously suppressed notifications or mail.
CREATE TABLE notification_events (
 event_id TEXT PRIMARY KEY REFERENCES issue_activity(id) ON DELETE CASCADE,
 created_at TEXT NOT NULL
);
-- A transient transaction workspace: source receipts authorize insertion, and
-- finalization consumes it before commit. It is never an inbox or delivery queue.
CREATE TABLE notification_candidates (
 event_id TEXT NOT NULL, issue_id TEXT NOT NULL REFERENCES issues(id) ON DELETE CASCADE,
 recipient_id TEXT NOT NULL REFERENCES operators(id) ON DELETE CASCADE,
 kind TEXT NOT NULL CHECK(kind IN ('assignment','mention','comment','intake_return','unblocked')),
 actor_id TEXT REFERENCES operators(id) ON DELETE SET NULL, actor_name TEXT,
 created_at TEXT NOT NULL, PRIMARY KEY(event_id,issue_id,recipient_id,kind)
);
CREATE TABLE notifications (
 id TEXT PRIMARY KEY, event_id TEXT NOT NULL,
 issue_id TEXT NOT NULL REFERENCES issues(id) ON DELETE CASCADE,
 recipient_id TEXT NOT NULL REFERENCES operators(id) ON DELETE CASCADE,
 actor_id TEXT REFERENCES operators(id) ON DELETE SET NULL, actor_name TEXT,
 causes_json TEXT NOT NULL CHECK(json_valid(causes_json) AND json_type(causes_json)='array'),
 created_at TEXT NOT NULL, read_at TEXT,
 UNIQUE(event_id,issue_id,recipient_id)
);
CREATE INDEX notifications_recipient_order ON notifications(recipient_id,created_at DESC,id DESC);
CREATE INDEX notifications_unread ON notifications(recipient_id) WHERE read_at IS NULL;
CREATE TABLE notification_deliveries (
 id TEXT PRIMARY KEY,
 notification_id TEXT NOT NULL UNIQUE REFERENCES notifications(id) ON DELETE CASCADE,
 recipient_id TEXT NOT NULL REFERENCES operators(id) ON DELETE CASCADE,
 actor_id TEXT REFERENCES operators(id) ON DELETE SET NULL, actor_name TEXT,
 identifier TEXT NOT NULL, title TEXT NOT NULL, app_link TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('pending','claimed','retry','accepted','development','uncertain','failed','suppressed')),
 attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 3),
 claim_token TEXT, claimed_at TEXT, next_attempt_at TEXT, reason TEXT,
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE INDEX notification_delivery_due ON notification_deliveries(status,next_attempt_at,created_at);
CREATE TABLE notification_delivery_attempts (
 id TEXT PRIMARY KEY, delivery_id TEXT NOT NULL REFERENCES notification_deliveries(id) ON DELETE CASCADE,
 number INTEGER NOT NULL CHECK(number BETWEEN 1 AND 3), status TEXT NOT NULL,
 reason TEXT, started_at TEXT NOT NULL, settled_at TEXT,
 UNIQUE(delivery_id,number)
);
-- Minimal retained automatic-action audit. No recipient, actor, title or body,
-- and deliberately no erasure cascade to the source issue or delivery.
CREATE TABLE notification_mail_audit (
 id TEXT PRIMARY KEY,
 feature TEXT NOT NULL CHECK(feature='notification.mail'),
 subject_identifier TEXT NOT NULL,
 outcome TEXT NOT NULL CHECK(outcome IN ('accepted','development')),
 created_at TEXT NOT NULL
);
CREATE TABLE notification_development_mail (
 delivery_id TEXT PRIMARY KEY REFERENCES notification_deliveries(id) ON DELETE CASCADE,
 recipient TEXT NOT NULL, subject TEXT NOT NULL, text TEXT NOT NULL, created_at TEXT NOT NULL
);
-- Recover explicit historical relationships only; no text scanning or fan-out.
INSERT OR IGNORE INTO issue_followers(issue_id,operator_id,created_at)
SELECT relation.issue_id,o.id,MIN(relation.created_at) FROM (
 SELECT issue_id,actor_operator_id AS operator_id,created_at FROM issue_activity WHERE kind='issue.created'
 UNION ALL SELECT id,assignee_operator_id,created_at FROM issues WHERE assignee_operator_id IS NOT NULL
 UNION ALL SELECT issue_id,actor_operator_id,created_at FROM issue_comments
) relation JOIN issues i ON i.id=relation.issue_id JOIN teams t ON t.id=i.team_id
JOIN operators o ON o.id=relation.operator_id AND o.workspace_id=t.workspace_id AND o.removed_at IS NULL
GROUP BY relation.issue_id,o.id;
-- Equal timestamp histories cannot identify a current decision reliably. Leave
-- ambiguous legacy deferrals unlinked instead of inventing their recipient.
INSERT INTO issue_deferral_origins(issue_id,decision_id)
SELECT i.id,d.id FROM issues i JOIN intake_decisions d ON d.issue_id=i.id
WHERE i.deferred_until IS NOT NULL AND d.kind='deferred' AND d.return_at=i.deferred_until
 AND d.created_at=(SELECT MAX(last.created_at) FROM intake_decisions last WHERE last.issue_id=i.id)
 AND 1=(SELECT count(*) FROM intake_decisions last WHERE last.issue_id=i.id AND last.created_at=d.created_at);

-- One optional parent per issue, kept beside the issue record so existing
-- issue rows are not rewritten. Deleting either issue removes the link, so the
-- direct children of a deleted parent become root issues.
CREATE TABLE issue_parents (
  issue_id TEXT PRIMARY KEY REFERENCES issues(id) ON DELETE CASCADE,
  parent_issue_id TEXT NOT NULL REFERENCES issues(id) ON DELETE CASCADE,
  created_at TEXT NOT NULL
);
CREATE INDEX issue_parents_parent_idx ON issue_parents(parent_issue_id, issue_id);

CREATE TRIGGER issue_parents_insert_guard BEFORE INSERT ON issue_parents
BEGIN
  SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM issues c JOIN teams ct ON ct.id=c.team_id JOIN issues p ON p.id=NEW.parent_issue_id JOIN teams pt ON pt.id=p.team_id WHERE c.id=NEW.issue_id AND pt.workspace_id=ct.workspace_id) THEN RAISE(ABORT,'issue_parent_workspace') END;
  SELECT CASE WHEN EXISTS(WITH RECURSIVE ancestors(id) AS (SELECT NEW.parent_issue_id UNION SELECT r.parent_issue_id FROM issue_parents r JOIN ancestors a ON r.issue_id=a.id) SELECT 1 FROM ancestors WHERE id=NEW.issue_id) THEN RAISE(ABORT,'issue_parent_cycle') END;
END;
CREATE TRIGGER issue_parents_update_guard BEFORE UPDATE OF issue_id,parent_issue_id ON issue_parents
BEGIN
  SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM issues c JOIN teams ct ON ct.id=c.team_id JOIN issues p ON p.id=NEW.parent_issue_id JOIN teams pt ON pt.id=p.team_id WHERE c.id=NEW.issue_id AND pt.workspace_id=ct.workspace_id) THEN RAISE(ABORT,'issue_parent_workspace') END;
  SELECT CASE WHEN EXISTS(WITH RECURSIVE ancestors(id) AS (SELECT NEW.parent_issue_id UNION SELECT r.parent_issue_id FROM issue_parents r JOIN ancestors a ON r.issue_id=a.id) SELECT 1 FROM ancestors WHERE id=NEW.issue_id) THEN RAISE(ABORT,'issue_parent_cycle') END;
END;
-- A linked issue cannot move to a team in another workspace.
CREATE TRIGGER issues_parent_team_guard BEFORE UPDATE OF team_id ON issues
WHEN NEW.team_id<>OLD.team_id
BEGIN
  SELECT CASE WHEN EXISTS(SELECT 1 FROM issue_parents r JOIN issues p ON p.id=r.parent_issue_id JOIN teams pt ON pt.id=p.team_id JOIN teams nt ON nt.id=NEW.team_id WHERE r.issue_id=NEW.id AND pt.workspace_id<>nt.workspace_id)
    OR EXISTS(SELECT 1 FROM issue_parents r JOIN issues c ON c.id=r.issue_id JOIN teams ct ON ct.id=c.team_id JOIN teams nt ON nt.id=NEW.team_id WHERE r.parent_issue_id=NEW.id AND ct.workspace_id<>nt.workspace_id) THEN RAISE(ABORT,'issue_parent_workspace') END;
END;
CREATE TRIGGER teams_parent_workspace_guard BEFORE UPDATE OF workspace_id ON teams
WHEN NEW.workspace_id<>OLD.workspace_id
BEGIN
  SELECT CASE WHEN EXISTS(SELECT 1 FROM issue_parents r JOIN issues c ON c.id=r.issue_id JOIN issues p ON p.id=r.parent_issue_id JOIN teams ct ON ct.id=c.team_id JOIN teams pt ON pt.id=p.team_id WHERE
    (c.team_id=NEW.id AND p.team_id<>NEW.id AND pt.workspace_id<>NEW.workspace_id) OR
    (p.team_id=NEW.id AND c.team_id<>NEW.id AND ct.workspace_id<>NEW.workspace_id)) THEN RAISE(ABORT,'issue_parent_workspace') END;
END;

-- Search is maintained in the source transaction: a failed index write aborts
-- the mutation, so committed source text cannot leave a stale search document.
CREATE INDEX issues_identifier_nocase ON issues(identifier COLLATE NOCASE);
CREATE INDEX issue_labels_label_search ON issue_labels(label_id,issue_id);
CREATE INDEX teams_workspace_search ON teams(workspace_id,archived_at);
CREATE INDEX operators_workspace_search ON operators(workspace_id,removed_at);
CREATE INDEX cycles_team_search ON cycles(team_id,closed_at);
CREATE INDEX saved_views_workspace_search ON saved_views(workspace_id,is_shared,owner_operator_id);

CREATE TABLE search_index_state (
 id INTEGER PRIMARY KEY CHECK(id=1),
 last_successful_index_at TEXT NOT NULL
);
INSERT INTO search_index_state VALUES(1,strftime('%Y-%m-%dT%H:%M:%fZ','now'));

CREATE VIRTUAL TABLE search_issues USING fts5(text, tokenize='unicode61 remove_diacritics 2', prefix='2 3 4');
CREATE VIRTUAL TABLE search_projects USING fts5(name, tokenize='unicode61 remove_diacritics 2', prefix='2 3 4');
CREATE VIRTUAL TABLE search_views USING fts5(name, tokenize='unicode61 remove_diacritics 2', prefix='2 3 4');

CREATE VIEW search_issue_documents AS
SELECT i.rowid AS rowid, i.id AS issue_id,
 i.identifier || ' ' || i.title || ' ' || i.description || ' ' ||
 coalesce(i.expected_outcome,'') || ' ' || coalesce(i.customer_impact,'') || ' ' ||
 coalesce((SELECT group_concat(c.body,' ') FROM issue_comments c
   WHERE c.issue_id=i.id AND c.deleted_at IS NULL),'') || ' ' ||
 coalesce((SELECT group_concat(e.summary,' ') FROM evidence_revisions e WHERE e.issue_id=i.id),'') || ' ' ||
 coalesce((SELECT p.name FROM projects p WHERE p.id=i.project_id AND p.workspace_id=t.workspace_id),'') || ' ' ||
 coalesce((SELECT group_concat(l.name,' ') FROM issue_labels il JOIN labels l ON l.id=il.label_id
   WHERE il.issue_id=i.id AND l.workspace_id=t.workspace_id),'') AS text
FROM issues i JOIN teams t ON t.id=i.team_id;

INSERT INTO search_issues(rowid,text) SELECT rowid,text FROM search_issue_documents;
INSERT INTO search_projects(rowid,name) SELECT rowid,name FROM projects;
INSERT INTO search_views(rowid,name) SELECT rowid,name FROM saved_views;

CREATE TRIGGER search_issue_insert AFTER INSERT ON issues BEGIN
 INSERT INTO search_issues(rowid,text) SELECT rowid,text FROM search_issue_documents WHERE issue_id=NEW.id;
