 until_at TEXT, until_change INTEGER NOT NULL CHECK(until_change IN(0,1)),
 snoozed_at TEXT NOT NULL, returned_at TEXT,
 CHECK((until_change=1 AND until_at IS NULL) OR (until_change=0 AND until_at IS NOT NULL))
);
